const CITY_INDEX = new Map(CITIES.map(([name, latitude, longitude, timeZone]) =>
  [name, { latitude, longitude, timeZone, name }]))

/**
 * Resolve a birthplace string. Returns null when nothing can be resolved —
 * the caller then leaves the Four Angles silent rather than inventing a place.
 *
 * Accepts "51.5, -0.12" (coordinates, no zone) or a city name from the table
 * (coordinates plus IANA zone, which is what allows an exact instant).
 */
export function resolveBirthplace(input) {
  const text = String(input ?? '').trim()
  if (!text) return null

  const pair = text.match(/^\s*(-?\d+(?:\.\d+)?)\s*[,;\s]\s*(-?\d+(?:\.\d+)?)\s*$/)
  if (pair) {
    const latitude = Number(pair[1])
    const longitude = Number(pair[2])
    if (Math.abs(latitude) > 90 || Math.abs(longitude) > 180) return null
    return { latitude, longitude, timeZone: null, source: 'coordinates', label: `${latitude}, ${longitude}` }
  }

  // City lookup: match on the portion before any comma, so "Kyoto, Japan" works.
  const key = text.toLowerCase().split(',')[0].trim().replace(/\s+/g, ' ')
  const hit = CITY_INDEX.get(key)
  if (!hit) return null
  return { latitude: hit.latitude, longitude: hit.longitude, timeZone: hit.timeZone, source: 'city', label: text.trim() }
}

export function knownPlaceCount() {
  return CITY_INDEX.size
}

