// --- Generative sigils: each seat's mark derived from its canonical geometry ---
export function sigilDataUri(glyph, opts = {}) {
  const ink = opts.ink || 'rgba(10,14,21,0.78)'
  const gold = opts.gold || '#B98438'
  const within = (glyph.number - 1) % 9
  const gi = glyph.groupIndex
  const P = a => {
    const r = a * Math.PI / 180
    return [50 + 40 * Math.cos(r), 50 + 40 * Math.sin(r)]
  }
  const arcAt = (r, a0, a1, w = 0.7, op = 0.55, stroke = ink) => {
    const p = a => [50 + r * Math.cos(a * Math.PI / 180), 50 + r * Math.sin(a * Math.PI / 180)]
    const [x0, y0] = p(a0), [x1, y1] = p(a1)
    const large = ((a1 - a0) % 360 + 360) % 360 > 180 ? 1 : 0
    return `<path d="M ${x0.toFixed(1)} ${y0.toFixed(1)} A ${r} ${r} 0 ${large} 1 ${x1.toFixed(1)} ${y1.toFixed(1)}" fill="none" stroke="${stroke}" stroke-width="${w}" opacity="${op}"/>`
  }
  let s = ''
  const gateA = (gi <= 9 ? gi * 36 : (gi === 10 ? 90 : -90)) - (gi <= 9 ? 90 : 0)
  // the frame dissolved: the inner ring stays, broken open toward the gate
  const innerR = 12 + within * 2.2
  s += arcAt(innerR, gateA + 24, gateA + 336, 0.7, 0.5)
  // the seam voice: a second broken ring, opened opposite
  if (glyph.seam) s += arcAt(innerR + 4.5, gateA + 204, gateA + 156 + 360, 0.7, 0.4)
  if (gi <= 9) {
    const a0 = gi * 36 - 90
    const [hx, hy] = P(a0)
    for (let k = 1; k <= 5; k++) {
      const [tx, ty] = P(a0 + k * 36)
      const vow = k === 3
      s += `<line x1="${hx.toFixed(2)}" y1="${hy.toFixed(2)}" x2="${tx.toFixed(2)}" y2="${ty.toFixed(2)}" stroke="${vow ? gold : ink}" stroke-width="${vow ? 1.1 : 0.7}" opacity="${vow ? 0.9 : 0.45}"/>`
    }
    s += `<circle cx="${hx.toFixed(2)}" cy="${hy.toFixed(2)}" r="2.6" fill="${gold}"/>`
  } else {
    s += `<line x1="50" y1="10" x2="50" y2="90" stroke="${ink}" stroke-width="0.9" opacity="0.6"/>`
    const y = gi === 10 ? 90 : 10
    s += `<circle cx="50" cy="${y}" r="2.6" fill="${gold}"/>`
  }
  if (glyph.invoked) s += `<circle cx="50" cy="50" r="2" fill="${gold}"/>`
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">${s}</svg>`
  return 'data:image/svg+xml,' + encodeURIComponent(svg).replace(/\(/g, '%28').replace(/\)/g, '%29').replace(/'/g, '%27')
}

// Lineage sigils: dodecagonal marks — one vertex per lineage, braid position encoded
// Central motif per lineage — one shared field-glyph grammar (broken concentric
// rings, nodes, threads), varied per lineage theme
function lineageMotif(name, ink, gold) {
  const arc = (cx, cy, r, a0, a1, stroke, w = 0.8, op = 1) => {
    const p = a => [cx + r * Math.cos(a * Math.PI / 180), cy + r * Math.sin(a * Math.PI / 180)]
    const [x0, y0] = p(a0), [x1, y1] = p(a1)
    const large = ((a1 - a0) % 360 + 360) % 360 > 180 ? 1 : 0
    return `<path d="M ${x0.toFixed(1)} ${y0.toFixed(1)} A ${r} ${r} 0 ${large} 1 ${x1.toFixed(1)} ${y1.toFixed(1)}" fill="none" stroke="${stroke}" stroke-width="${w}" opacity="${op}"/>`
  }
  const node = (x, y, r, fill) => `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r}" fill="${fill}"/>`
  const at = (r, a) => [50 + r * Math.cos(a * Math.PI / 180), 50 + r * Math.sin(a * Math.PI / 180)]
  const m = {
    // Vega — Memory Keepers: rings broken where memory slips; one gold moment kept, threaded to centre
    'Vega': (() => {
      let s = [[6, -60, 205], [10, 40, 275], [14, -140, 75], [18, 115, 330]]
        .map(([r, a0, a1]) => arc(50, 50, r, a0, a1, ink, 0.8, 0.95 - r * 0.02)).join('')
      const [kx, ky] = at(14, 75)
      return s + `<line x1="50" y1="50" x2="${kx.toFixed(1)}" y2="${ky.toFixed(1)}" stroke="${gold}" stroke-width="0.7" opacity="0.7"/>` + node(kx, ky, 1.7, gold) + node(50, 50, 1, ink)
    })(),
    // Lyra — Sound & Word Weavers: every ring opens eastward, wider as it travels — a broadcast leaving the field
    'Lyra': (() => {
      const s = [[6, 18], [10, 26], [14, 34], [18, 42]]
        .map(([r, g]) => arc(50, 50, r, g, 360 - g, ink, 0.8, 1.02 - r * 0.02)).join('')
      const [tx, ty] = at(22, 0)
      return s + node(50, 50, 1.2, ink) + node(tx, ty, 1.7, gold)
    })(),
    // Arcturus — Sacred Devotionals: rings parted at the crown; a gold thread rises through the opening
    'Arcturus': (() => {
      const s = [[7, 22], [12, 16], [17, 11]]
        .map(([r, g]) => arc(50, 50, r, -90 + g, 270 - g, ink, 0.8, 1.04 - r * 0.02)).join('')
      return s + `<line x1="50" y1="52" x2="50" y2="30" stroke="${gold}" stroke-width="0.8"/>` + node(50, 29, 1.6, gold) + node(50, 54, 1, ink)
    })(),
    // Orion — Chaos Catalysts: two ring-fields interfering; gold spark where they cross
    'Orion': (() => {
      let s = [[5, 60, 350], [9, 130, 55]].map(([r, a0, a1]) => arc(43.5, 50, r, a0, a1, ink, 0.8)).join('')
      s += [[5, 240, 170], [9, -50, 235]].map(([r, a0, a1]) => arc(56.5, 50, r, a0, a1, ink, 0.8)).join('')
      return s + node(50, 50, 1.6, gold)
    })(),
    // Aldebaran — Beauty Makers: arcs unfurling by the golden ratio — a spiral told in rings
    'Aldebaran': (() => {
      let s = '', r = 4, a0 = -90
      for (let i = 0; i < 4; i++) { s += arc(50, 50, r, a0, a0 + 205 - i * 18, ink, 0.8, 1 - i * 0.08); a0 += 137.5; r *= 1.618 }
      const [gx2, gy2] = at(4, -90)
      return s + node(gx2, gy2, 1.5, gold)
    })(),
    // Sirius — Teachers & Patterners: gaps in strict cadence — a calibrated field
    'Sirius': (() => {
      let s = ''
      ;[7, 12, 17].forEach((r, i) => { for (let k = 0; k < 4; k++) s += arc(50, 50, r, k * 90 + 8 + i * 30, (k + 1) * 90 - 8 + i * 30, ink, 0.8, 1 - i * 0.1) })
      const [sx, sy] = at(17, 30 * 2 - 90)
      return s + node(50, 50, 1.1, ink) + node(sx, sy, 1.6, gold)
    })(),
    // Antares — Deathwalkers: every ring opens on the same downward corridor — the passage through
    'Antares': (() => {
      const s = [[6, 14], [10, 11], [14, 9], [18, 7]]
        .map(([r, g]) => arc(50, 50, r, 90 + g, 90 - g + 360, ink, 0.8, 1.04 - r * 0.018)).join('')
      const [ox, oy] = at(21, 90)
      return s + node(ox, oy, 1.6, gold)
    })(),
    // Andromeda — Innovators & Futurists: each ring's opening advances — the field mid-turn
    'Andromeda': (() => {
      const s = [[6, 0], [10, 50], [14, 100], [18, 150]]
        .map(([r, lead]) => arc(50, 50, r, -90 + lead + 30, -90 + lead + 360 - 30, ink, 0.8, 1.04 - r * 0.018)).join('')
      const [lx, ly] = at(18, -90 + 150)
      return s + node(lx, ly, 1.6, gold)
    })(),
    // Alpha Centauri — Lovers & Relationals: two ring-fields, each broken toward the other; gold at the shared point
    'Alpha Centauri': (() => {
      let s = [[4.5, 40], [8, 55]].map(([r, g]) => arc(44, 50, r, g, 360 - g, ink, 0.8)).join('')
      s += [[4.5, 40], [8, 55]].map(([r, g]) => arc(56, 50, r, 180 + g, 180 - g + 360, ink, 0.8)).join('')
      return s + node(50, 50, 1.6, gold)
    })(),
    // Pleiades — Incarnates & Earth Stewards: seven seeds held inside one parted ring
    'Pleiades': (() => {
      let s = arc(50, 50, 17, -78, 258, ink, 0.8)
      ;[[50, 50], [50, 43], [56, 46.5], [56, 53.5], [50, 57], [44, 53.5], [44, 46.5]].forEach(([x, y], i) => { s += node(x, y, 1.4, i === 0 ? gold : ink) })
      return s
    })(),
    // Galactic Core — the Deep Court: the field nearly closed; one gold veil arc
    'Galactic Core': (() => {
      let s = node(50, 50, 6.5, ink).replace('/>', ` opacity="0.85"/>`)
      s += [[11, 100, 80], [16, 275, 262]].map(([r, a0, a1]) => arc(50, 50, r, a0, a1 + 360, ink, 0.8, 0.8)).join('')
      return s + arc(50, 50, 11, 115, 155, gold, 0.9)
    })(),
    // Polaris — the Crown Court: the one unbroken ring; the field that holds
    'Polaris': (() => {
      let s = arc(50, 50, 13, 0, 359.99, ink, 0.9)
      ;[0, 90, 180, 270].forEach(a => { const [x0, y0] = at(15, a - 90), [x1, y1] = at(18.5, a - 90); s += `<line x1="${x0.toFixed(1)}" y1="${y0.toFixed(1)}" x2="${x1.toFixed(1)}" y2="${y1.toFixed(1)}" stroke="${ink}" stroke-width="0.8"/>` })
      return s + node(50, 50, 1.8, gold)
    })(),
  }
  const key = Object.keys(m).find(k => name && name.toLowerCase().includes(k.toLowerCase()))
  return key ? m[key] : ''
}

export function lineageSigilDataUri(index, opts = {}) {
  const ink = opts.ink || 'rgba(10,14,21,0.78)'
  const gold = opts.gold || '#B98438'
  // the field-glyph alone — the old dodecagon frame is dissolved
  const s = `<g transform="translate(50 50) scale(1.85) translate(-50 -50)">${lineageMotif(opts.name, ink, gold)}</g>`
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">${s}</svg>`
  return 'data:image/svg+xml,' + encodeURIComponent(svg).replace(/\(/g, '%28').replace(/\)/g, '%29').replace(/'/g, '%27')
}

// The Wheel of 108 — full chart-wheel background (structure only; tap dots are DOM)
export function wheelDataUri(opts = {}) {
  const ink = opts.ink || 'rgba(10,14,21,0.55)'
  const gold = opts.gold || '#B98438'
  const P = (a, r) => {
    const rad = a * Math.PI / 180
    return [50 + r * Math.cos(rad), 50 + r * Math.sin(rad)]
  }
  let s = `<circle cx="50" cy="50" r="46" fill="none" stroke="${ink}" stroke-width="0.5"/>`
  s += `<circle cx="50" cy="50" r="37" fill="none" stroke="${ink}" stroke-width="0.3" opacity="0.5"/>`
  s += `<circle cx="50" cy="50" r="17" fill="none" stroke="${ink}" stroke-width="0.3" opacity="0.5"/>`
  for (let k = 0; k < 10; k++) {
    const a = k * 36 - 90
    const [gx, gy] = P(a, 46)
    const [ix, iy] = P(a, 17)
    s += `<line x1="${ix.toFixed(2)}" y1="${iy.toFixed(2)}" x2="${gx.toFixed(2)}" y2="${gy.toFixed(2)}" stroke="${ink}" stroke-width="0.3" opacity="0.35"/>`
    s += `<circle cx="${gx.toFixed(2)}" cy="${gy.toFixed(2)}" r="1" fill="${gold}"/>`
  }
  s += `<line x1="50" y1="33" x2="50" y2="67" stroke="${ink}" stroke-width="0.3" opacity="0.5"/>`
  s += `<circle cx="50" cy="50" r="0.8" fill="${gold}"/>`
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">${s}</svg>`
  return 'data:image/svg+xml,' + encodeURIComponent(svg).replace(/\(/g, '%28').replace(/\)/g, '%29').replace(/'/g, '%27')
}

// Seat position on the Wheel of 108, in percent of the square
export function wheelSeatPosition(glyph) {
  const gi = glyph.groupIndex
  const within = (glyph.number - 1) % 9
  let angle, r
  if (gi <= 9) {
    angle = gi * 36 - 90 - 12.8 + within * 3.2
    r = 41.5
  } else {
    const base = gi === 11 ? -90 : 90 // zenith top, nadir bottom
    angle = base - 12.8 + within * 3.2
    r = 24.5
  }
  const rad = angle * Math.PI / 180
  return { left: 50 + r * Math.cos(rad), top: 50 + r * Math.sin(rad) }
}

// Dodecahedron face: pentagon of observatory glass carrying a ring of nine seats
export function dodecaFaceDataUri(seats, opts = {}) {
  const ink = 'rgba(10,14,21,0.55)'
  const gold = '#B98438'
  const off = opts.pointDown ? 36 : 0 // point-down faces share their flat top edge with the face above
  const P = (a, r) => [55 + r * Math.cos((a + off - 90) * Math.PI / 180), 55 + r * Math.sin((a + off - 90) * Math.PI / 180)]
  const pts = [0, 72, 144, 216, 288].map(a => P(a, 46).map(v => v.toFixed(2)).join(',')).join(' ')
  let s = `<polygon points="${pts}" fill="rgba(241,232,214,0.8)" stroke="${ink}" stroke-width="0.9"/>`
  const [gx, gy] = P(0, 46)
  s += `<circle cx="${gx.toFixed(2)}" cy="${gy.toFixed(2)}" r="2.2" fill="${gold}"/>`
  seats.forEach((seat, i) => {
    const [x, y] = P(i * 40, 25)
    s += `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="1.7" fill="${seat.seam ? gold : ink}"/>`
  })
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 110 110">${s}</svg>`
  return 'data:image/svg+xml,' + encodeURIComponent(svg).replace(/\(/g, '%28').replace(/\)/g, '%29').replace(/'/g, '%27')
}

// The twelve face placements of the dodecahedral mandala (CSS 3D transforms).
// Zenith crowns the top, Nadir grounds the bottom; upper-course rings form the
// upper band, lower-course rings the lower — the canon's own arrangement.
export function dodecaFaces(groups, edge = 54) {
  const r = 1.113516 * edge // inradius
  const tilt = 26.565 // 90 - half dihedral
  const upper = [], lower = []
  groups.forEach((g, i) => {
    if (g.course === 'upper') upper.push(i)
    else if (g.course === 'lower') lower.push(i)
  })
  const faces = []
  faces.push({ index: 11, transform: `rotateX(90deg) translateZ(${r.toFixed(1)}px)`, pointDown: false })
  faces.push({ index: 10, transform: `rotateX(-90deg) translateZ(${r.toFixed(1)}px)`, pointDown: true })
  upper.forEach((gi, k) => faces.push({ index: gi, transform: `rotateY(${k * 72}deg) rotateX(${tilt}deg) translateZ(${r.toFixed(1)}px)`, pointDown: true }))
  lower.forEach((gi, k) => faces.push({ index: gi, transform: `rotateY(${k * 72 + 36}deg) rotateX(${-tilt}deg) translateZ(${r.toFixed(1)}px)`, pointDown: false }))
  return faces
}

// Chord sigils — each of the five angles drawn as its own field-glyph,
// angle-true where the geometry carries meaning
export function chordSigilDataUri(offset, opts = {}) {
  const ink = opts.ink || 'rgba(10,14,21,0.78)'
  const gold = opts.gold || '#B98438'
  const at = (r, a) => [50 + r * Math.cos((a - 90) * Math.PI / 180), 50 + r * Math.sin((a - 90) * Math.PI / 180)]
  const arc = (r, a0, a1, stroke, w = 0.8, op = 1) => {
    const [x0, y0] = at(r, a0), [x1, y1] = at(r, a1)
    const large = ((a1 - a0) % 360 + 360) % 360 > 180 ? 1 : 0
    return `<path d="M ${x0.toFixed(1)} ${y0.toFixed(1)} A ${r} ${r} 0 ${large} 1 ${x1.toFixed(1)} ${y1.toFixed(1)}" fill="none" stroke="${stroke}" stroke-width="${w}" opacity="${op}"/>`
  }
  const node = (x, y, r, fill) => `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r}" fill="${fill}"/>`
  const line = (x0, y0, x1, y1, stroke, w = 0.8, op = 1) => `<line x1="${x0.toFixed(1)}" y1="${y0.toFixed(1)}" x2="${x1.toFixed(1)}" y2="${y1.toFixed(1)}" stroke="${stroke}" stroke-width="${w}" opacity="${op}"/>`
  let s = ''
  if (offset === 1) {
    // The Step 36° — succession: an inner ring opens exactly where an outer ring begins;
    // one prepares, the other receives. The handing point is gold.
    s += arc(20, 18, 306, ink, 1, 0.9)
    s += arc(32, 342, 234 + 360 - 90, ink, 1, 0.55)
    const [hx, hy] = at(26, -18)
    s += line(...at(20, -54), ...at(32, -18), ink, 0.9, 0.5)
    s += node(hx, hy, 2.4, gold)
    s += node(...at(20, 126), 1.8, ink)
  } else if (offset === 2) {
    // The Gift 72° — the pentagon's step: five seats implied, two of them singing
    // together without effort; their chord in gold, the other three left faint
    for (let k = 0; k < 5; k++) {
      const a = k * 72
      s += arc(36, a + 12, a + 60, ink, 1, k < 2 ? 0.9 : 0.35)
    }
    const [ax, ay] = at(36, 0), [bx, by] = at(36, 72)
    s += line(ax, ay, bx, by, gold, 1.2, 0.9)
    s += node(ax, ay, 2, ink)
    s += node(bx, by, 2.4, gold)
  } else if (offset === 3) {
    // The Vow 108° — the pentagon's corner held open: two arms meeting at a
    // true 108°, the oath a gold thread joining their far ends
    const [vx, vy] = [50, 68]
    const a1 = -90 - 54, a2 = -90 + 54 // 108° between arms, opening upward
    const [e1x, e1y] = [vx + 40 * Math.cos(a1 * Math.PI / 180), vy + 40 * Math.sin(a1 * Math.PI / 180)]
    const [e2x, e2y] = [vx + 40 * Math.cos(a2 * Math.PI / 180), vy + 40 * Math.sin(a2 * Math.PI / 180)]
    s += line(vx, vy, e1x, e1y, ink, 1.1)
    s += line(vx, vy, e2x, e2y, ink, 1.1)
    // witness arc inside the corner, centred on the vertex
    const wr = 12
    const [w1x, w1y] = [vx + wr * Math.cos(a1 * Math.PI / 180), vy + wr * Math.sin(a1 * Math.PI / 180)]
    const [w2x, w2y] = [vx + wr * Math.cos(a2 * Math.PI / 180), vy + wr * Math.sin(a2 * Math.PI / 180)]
    s += `<path d="M ${w1x.toFixed(1)} ${w1y.toFixed(1)} A ${wr} ${wr} 0 0 1 ${w2x.toFixed(1)} ${w2y.toFixed(1)}" fill="none" stroke="${ink}" stroke-width="0.8" opacity="0.4"/>`
    s += line(e1x, e1y, e2x, e2y, gold, 1.1, 0.85)
    s += node(vx, vy, 1.8, ink)
    s += node(e1x, e1y, 1.8, ink)
    s += node(e2x, e2y, 2.4, gold)
  } else if (offset === 4) {
    // The Spiral 144° — long-arc weaving: arcs advancing by 144° each turn,
    // widening as the pattern completes across spans no life will see
    let a = -90, r = 10
    for (let i = 0; i < 4; i++) {
      s += arc(r, a, a + 144, ink, 1, 0.95 - i * 0.18)
      a += 144; r += 8
    }
    s += node(...at(10, -90), 1.8, ink)
    s += node(...at(34, -90 + 144 * 4), 2.4, gold)
  } else {
    // The Mirror 180° — two half-rings facing each other across the centre;
    // the diameter in gold passes through what refuses to be skipped
    s += arc(34, 100, 260, ink, 1.05, 0.9)
    s += arc(34, 280, 80 + 360, ink, 1.05, 0.9)
    const [ax, ay] = at(34, -90), [bx, by] = at(34, 90)
    s += line(ax, ay, bx, by, gold, 1.2, 0.9)
    s += node(50, 50, 2.2, gold)
    s += node(ax, ay, 1.8, ink)
    s += node(bx, by, 1.8, ink)
  }
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">${s}</svg>`
  return 'data:image/svg+xml,' + encodeURIComponent(svg).replace(/\(/g, '%28').replace(/\)/g, '%29').replace(/'/g, '%27')
}

// The chord lattice drawn flat: computed chords as gold lines across the ecliptic wheel.
// Canonical chart orientation — 0° at the left, longitudes increasing counterclockwise.
export function latticeDataUri(chords, points, opts = {}) {
  const ink = opts.ink || 'rgba(10,14,21,0.6)'
  const gold = opts.gold || '#B98438'
  const at = (lon, r) => {
    const th = (180 - lon) * Math.PI / 180
    return [50 + r * Math.cos(th), 50 - r * Math.sin(th)]
  }
  let s = `<circle cx="50" cy="50" r="46" fill="none" stroke="${ink}" stroke-width="0.5"/>`
  for (let k = 0; k < 12; k++) {
    const [x0, y0] = at(k * 30, 46), [x1, y1] = at(k * 30, 43.5)
    s += `<line x1="${x0.toFixed(1)}" y1="${y0.toFixed(1)}" x2="${x1.toFixed(1)}" y2="${y1.toFixed(1)}" stroke="${ink}" stroke-width="0.4" opacity="0.6"/>`
  }
  const tierOp = { lattice: 0.9, working: 0.6, whisper: 0.3 }
  const lonOf = new Map(points.map(p => [p.name, p.longitude]))
  chords.forEach(ch => {
    const la = lonOf.get(ch.first), lb = lonOf.get(ch.second)
    if (la == null || lb == null) return
    const [ax, ay] = at(la, 42), [bx, by] = at(lb, 42)
    s += `<line x1="${ax.toFixed(1)}" y1="${ay.toFixed(1)}" x2="${bx.toFixed(1)}" y2="${by.toFixed(1)}" stroke="${gold}" stroke-width="0.8" opacity="${tierOp[ch.tier] ?? 0.4}"/>`
  })
  const used = new Set(chords.flatMap(ch => [ch.first, ch.second]))
  points.forEach(p => {
    if (!used.has(p.name)) return
    const [x, y] = at(p.longitude, 42)
    s += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${p.planet ? 1.9 : 1.3}" fill="${p.planet ? gold : ink}"/>`
  })
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">${s}</svg>`
  return 'data:image/svg+xml,' + encodeURIComponent(svg).replace(/\(/g, '%28').replace(/\)/g, '%29').replace(/'/g, '%27')
}

// ─────────────────────────────────────────────────────────────
// src-phone/ephemeris.js
// ─────────────────────────────────────────────────────────────

// Fixture glyph longitudes (golden-angle spread) — used when the ephemeris service is unreachable.
// Keyed by catalogue command, not name, so seam seats stay distinct downstream.
export function fixtureLongitudes(glyphs) {
  const lonByName = new Map()
  const placements = []
  const seen = new Set()
  glyphs.forEach(g => {
    const longitude = (g.number * 137.50776405) % 360
    if (!lonByName.has(g.name)) lonByName.set(g.name, longitude)
    const command = g.catalogueId?.horizonsCommand
    if (command && !seen.has(command)) {
      seen.add(command)
      placements.push({ command, name: g.name, longitude })
    }
  })
  return withPlacements(lonByName, placements)
}

// The interface reads the returned Map directly (name → longitude), while the
// reading pass needs catalogue commands to reach seat-level joins. Carry both
// rather than making the caller choose.
function withPlacements(lonByName, placements) {
  Object.defineProperty(lonByName, 'placements', { value: placements, enumerable: false })
  return lonByName
}

// The repo's own service protocol (server/server.js): POST { timestamp, bodies:[{command,name,seat}] }
export function uniqueBodies(glyphs) {
  const byCommand = new Map()
  glyphs.forEach(g => {
    const num = g.catalogue.match(/\((\d+)\)/)?.[1]
    if (num && !byCommand.has(num)) byCommand.set(num, { command: num + ';', name: g.name })
  })
  return [...byCommand.values()]
}
export async function fetchGlyphLongitudes(glyphs, timestamp, endpoint) {
  const bodies = uniqueBodies(glyphs)
  const lonByName = new Map()
  const placements = []
  for (let i = 0; i < bodies.length; i += 8) {
    const res = await fetch(endpoint, {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ timestamp, bodies: bodies.slice(i, i + 8) }),
      signal: AbortSignal.timeout(30000),
    })
    const data = await res.json()
    if (!res.ok) throw new Error(data.error || 'ephemeris failed')
    data.placements.forEach(p => {
      if (!lonByName.has(p.name)) lonByName.set(p.name, p.longitude)
      placements.push({ command: p.command, name: p.name, longitude: p.longitude, latitude: p.latitude })
    })
  }
  return withPlacements(lonByName, placements)
}

// --- Direct NASA/JPL Horizons access ---
// NOT reachable from a browser: Horizons returns no Access-Control-Allow-Origin
// and answers OPTIONS with 405, so a cross-origin fetch always fails. Kept
// because it works wherever CORS does not apply (Node, a native shell); in the
// browser this tier always falls through to the fixtures below. The phone app
// therefore needs the Codex ephemeris service, local or hosted, for real sky.
// Query + parser ported verbatim from server/horizons.js
export const HORIZONS_ENDPOINT = 'https://ssd.jpl.nasa.gov/api/horizons.api'
export function horizonsUrl(command, timestamp) {
  if (!/^\d+;?$/.test(command)) throw new TypeError('Horizons command must be numeric.')
  const parameters = new URLSearchParams({
    format: 'json', COMMAND: `'${command}'`, OBJ_DATA: 'NO', MAKE_EPHEM: 'YES',
    // Repo `julianDate` takes a Date; this function is handed an ISO string.
    EPHEM_TYPE: 'OBSERVER', CENTER: "'500@399'", TLIST: `'${julianDate(new Date(timestamp)).toFixed(8)}'`,
    TLIST_TYPE: 'JD', TIME_TYPE: 'UT', TIME_DIGITS: 'FRACSEC', QUANTITIES: "'31'", CSV_FORMAT: 'YES',
  })
  return `${HORIZONS_ENDPOINT}?${parameters}`
}
export function parseHorizonsPlacement(payload) {
  if (payload.error) throw new Error(`Horizons: ${payload.error}`)
  const table = payload.result?.match(/\$\$SOE\s*\n([^\n]+)\n\$\$EOE/)?.[1]
  if (!table) throw new Error('Horizons returned no ephemeris row.')
  const fields = table.split(',').map(f => f.trim()).filter(Boolean)
  const longitude = Number(fields.at(-2))
  const latitude = Number(fields.at(-1))
  if (!Number.isFinite(longitude) || !Number.isFinite(latitude)) throw new Error('Invalid ecliptic position.')
  return { longitude, latitude }
}
async function mapConcurrent(items, limit, operation) {
  const output = new Array(items.length)
  let cursor = 0
  async function worker() {
    while (cursor < items.length) { const i = cursor++; output[i] = await operation(items[i], i) }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker))
  return output
}
// Direct fetch of all unique glyph bodies, cached per body+instant in localStorage
export async function fetchGlyphLongitudesDirect(glyphs, timestamp, onProgress = () => {}) {
  const bodies = uniqueBodies(glyphs)
  const iso = new Date(timestamp).toISOString()
  const lonByName = new Map()
  const placements = []
  let done = 0
  await mapConcurrent(bodies, 3, async body => {
    const key = 'glcx_eph_' + body.command + '|' + iso
    let placement
    try { placement = JSON.parse(localStorage.getItem(key)) } catch (e) { placement = null }
    if (!placement) {
      const res = await fetch(horizonsUrl(body.command, iso), { signal: AbortSignal.timeout(30000) })
      if (!res.ok) throw new Error('Horizons HTTP ' + res.status)
      placement = parseHorizonsPlacement(await res.json())
      try { localStorage.setItem(key, JSON.stringify(placement)) } catch (e) { /* cache full — proceed uncached */ }
    }
    if (!lonByName.has(body.name)) lonByName.set(body.name, placement.longitude)
    placements.push({ command: body.command, name: body.name, longitude: placement.longitude, latitude: placement.latitude })
    onProgress({ completed: ++done, total: bodies.length })
  })
  return withPlacements(lonByName, placements)
}

// ─────────────────────────────────────────────────────────────
// src-phone/sample.js
// ─────────────────────────────────────────────────────────────

// Deterministic sample chart (golden-angle spread). Illustrative only — never a real sky.
export function computeSampleReading(glyphs) {
  const lonByName = new Map()
  glyphs.forEach(g => { if (!lonByName.has(g.name)) lonByName.set(g.name, (g.number * 137.50776405) % 360) })
  const unique = [...lonByName.entries()].map(([name, longitude]) => {
    const g = glyphs.find(x => x.name === name)
    return { name, longitude, glyph: g }
  })
  const L = name => lonByName.get(name) || 0
  const natal = [
    { name: 'Sun', longitude: L('Pallas Athene') + 0.31 },
    { name: 'Moon', longitude: L('Psyche') + 0.87 },
    { name: 'Mercury', longitude: L('Hermes') + 1.62 },
    { name: 'Venus', longitude: L('Aphrodite') + 0.12 },
    { name: 'Mars', longitude: L('Eris') + 2.41 },
    { name: 'Jupiter', longitude: L('Logos') + 0.55 },
    { name: 'Saturn', longitude: L('Orcus') + 1.08 },
    { name: 'Uranus', longitude: L('Prometheus') + 0.05 },
    { name: 'Neptune', longitude: L('Salacia') + 2.9 },
    { name: 'Pluto', longitude: L('Persephone') + 0.72 },
  ]
  const conjunctions = []
  natal.forEach(p => unique.forEach(u => {
    const c = conjunction(u.longitude, p.longitude)
    if (c) conjunctions.push({ glyph: u.glyph, planet: p.name, ...c })
  }))
  conjunctions.sort((a, b) => a.orb - b.orb)
  const courts = natal.map(p => ({
    planet: p.name,
    contacts: conjunctions.filter(c => c.planet === p.name)
  })).filter(c => c.contacts.length).sort((a, b) => b.contacts.length - a.contacts.length)
  const points = [...unique.map(u => ({ name: u.name, longitude: u.longitude, glyph: u.glyph })), ...natal.map(p => ({ name: p.name, longitude: p.longitude }))]
  const tierRank = { lattice: 0, working: 1, whisper: 2 }
  const chords = []
  for (let i = 0; i < points.length; i++) for (let j = i + 1; j < points.length; j++) {
    const c = decagonalChord(points[i].longitude, points[j].longitude)
    // Repo `decagonalChord` names the family `aspect`; the interface binds `name`.
    if (c) chords.push({ first: points[i].name, second: points[j].name, ...c, name: c.aspect })
  }
  chords.sort((a, b) => tierRank[a.tier] - tierRank[b.tier] || a.orb - b.orb)
  const live = [
    { name: 'Sun', longitude: L('Polyhymnia') + 0.22 },
    { name: 'Venus', longitude: L('Juno') + 0.64 },
    { name: 'Mars', longitude: L('Hekate') + 1.35 },
  ]
  const activations = []
  live.forEach(p => unique.forEach(u => {
    const c = conjunction(u.longitude, p.longitude)
    if (c) activations.push({ glyph: u.glyph, planet: p.name, ...c })
  }))
  activations.sort((a, b) => a.orb - b.orb)
  return { conjunctions: conjunctions.slice(0, 6), courts: courts.slice(0, 3), chords: chords.slice(0, 5), activations: activations.slice(0, 3) }
}

// ─────────────────────────────────────────────────────────────
// src-phone/reading-pass.js
// ─────────────────────────────────────────────────────────────

// The full reading pass for the phone app.
//
// The shipped phone build computed four things — conjunctions, courts, chords,
// activations — while its interface named seven layers. Layers iv-vii were
// prose. This module runs the canon's real analysis (src/gates.js,
// src/reading.js, src/synthesis.js) behind those names, and keeps the exact
// output shapes the interface already binds to.
//
// Seats, not names: glyph names repeat across the nine seam (`glyph.seam`), so
// a name-keyed map silently drops one of every seam pair. Everything here joins
// through `placementsBySeat`, keyed by seat number.

const CONJUNCTION_RANK = { exact: 0, working: 1, whisper: 2 }
const CHORD_RANK = { lattice: 0, working: 1, whisper: 2 }

// Placements carry the catalogue command; a Map keyed by name cannot express a
// seam. Fetchers attach `.placements` to the Map they return, so prefer it and
// reconstruct only when a caller hands us a bare legacy map.
function placementsFrom(glyphs, source) {
  if (Array.isArray(source)) return source
  if (source && Array.isArray(source.placements)) return source.placements
  const byName = source instanceof Map ? source : new Map()
  const seen = new Map()
  glyphs.forEach(glyph => {
    if (!glyph.catalogueId || !byName.has(glyph.name)) return
    const command = glyph.catalogueId.horizonsCommand
    if (!seen.has(command)) seen.set(command, { command, name: glyph.name, longitude: byName.get(glyph.name) })
  })
  return [...seen.values()]
}

function longitudeView(placementsMap) {
  const view = new Map()
  placementsMap.forEach(placement => {
    if (!view.has(placement.name)) view.set(placement.name, placement.longitude)
  })
  return view
}

function withCommands(planets) {
  return planets.map(planet => {
    const body = MAJOR_BODIES.find(candidate => candidate.name === planet.name)
    return body ? { ...planet, command: body.command } : { ...planet }
  })
}

function themeOf(glyph) {
  return glyph?.function || null
}

// A seam body holds two seats, so a list built from seats names it twice. The
// two seats are a real feature of the canon, but prose that says "Anubis,
// Anubis" reads as a fault rather than as a seam. Name it once, and say so.
function distinctNames(glyphList) {
  const seen = new Set()
  return glyphList.filter(glyph => {
    if (!glyph || seen.has(glyph.name)) return false
    seen.add(glyph.name)
    return true
  }).map(glyph => glyph.name + (glyph.seam ? ' (at both its seats)' : ''))
}

// --- Evidence records feeding src/synthesis.js -------------------------------

function clusterEvidence(cluster, glyphs) {
  if (!cluster || cluster.members.length < 2) return null
  const seats = cluster.seats
  const named = seats.map(seat => glyphs.find(glyph => glyph.number === seat)).filter(Boolean)
  const names = distinctNames(named)
  return {
    id: 'cluster',
    kind: 'cluster',
    count: cluster.members.length,
    orb: cluster.span,
    measurement: `${cluster.members.length} unique bodies within ${cluster.span.toFixed(2)}°, centred ${cluster.center.toFixed(2)}°`,
    canonicalSeats: seats,
    themes: named.map(themeOf).filter(Boolean),
    transmission: names.length
      ? `The densest gathering in this sky holds ${names.slice(0, 4).join(', ')}${names.length > 4 ? ` and ${names.length - 4} more` : ''} inside ${cluster.span.toFixed(2)}°. Read them as one crowded office rather than separate voices: they share a task, and they share its tension.`
      : `A gathering of ${cluster.members.length} bodies closes to ${cluster.span.toFixed(2)}° — concentration without a named seat, which is recorded and not interpreted further.`,
  }
}

function courtEvidence(courts) {
  return courts.filter(court => court.contacts.length).slice(0, 3).map((court, index) => {
    const tightest = court.contacts[0]
    const names = distinctNames(court.contacts.map(contact => contact.glyph))
    return {
      id: `court-${court.body.name.toLowerCase()}`,
      kind: 'court',
      tier: tightest.tier,
      orb: tightest.orb,
      count: court.contacts.length,
      measurement: `${court.body.name} holds ${court.contacts.length} seat${court.contacts.length === 1 ? '' : 's'}; tightest ${tightest.glyph.name} at ${tightest.orb.toFixed(3)}°`,
      canonicalSeats: court.contacts.map(contact => contact.glyph.number),
      themes: court.contacts.map(contact => themeOf(contact.glyph)).filter(Boolean),
      sourceIndex: index,
      transmission: `${court.body.name} keeps a court of ${names.length}: ${names.slice(0, 3).join(', ')}${names.length > 3 ? `, and ${names.length - 3} more` : ''}. These offices are not separate appointments — they answer to one another through the planet that holds them.`,
    }
  })
}

function gateEvidence(loudest) {
  return loudest.slice(0, 3).map(gate => {
    const tightest = gate.contacts[0]
    const label = tightest.glyph?.name ?? tightest.point?.name ?? 'a measured point'
    return {
      id: `gate-${gate.gate}`,
      kind: 'gate',
      tier: tightest.tier,
      orb: tightest.orb,
      count: gate.contacts.length,
      measurement: `Gate ${gate.gate} ${gate.name} occupied by ${label} at ${tightest.orb.toFixed(3)}°`,
      canonicalSeats: gate.contacts.filter(contact => contact.glyph).map(contact => contact.glyph.number),
      themes: [gate.phase].filter(Boolean),
      transmission: `The ${gate.name} is occupied — ${label} stands at ${tightest.orb.toFixed(2)}° from its degree. This is the phase of the walk named "${gate.phase}", and this sky speaks from it rather than passing through.`,
    }
  })
}

function angleEvidence(angles, confidence) {
  if (!angles) return []
  return angles.filter(angle => angle.contacts.length).slice(0, 2).map(angle => {
    const tightest = angle.contacts[0]
    return {
      id: `angle-${angle.key}`,
      kind: 'angle',
      tier: tightest.tier,
      orb: tightest.orb,
      count: angle.contacts.length,
      confidence,
      measurement: `${angle.label} conjunct ${tightest.glyph.name} at ${tightest.orb.toFixed(3)}°${confidence === 'approximate' ? ' (approximate angle)' : ''}`,
      canonicalSeats: angle.contacts.map(contact => contact.glyph.number),
      themes: angle.contacts.map(contact => themeOf(contact.glyph)).filter(Boolean),
      transmission: `${tightest.glyph.name} sits on the ${angle.label}${confidence === 'approximate' ? ', at an angle computed from an approximate instant' : ''}. An angle is where a seat becomes visible to others rather than held privately.`,
    }
  })
}

function chordEvidence(chords) {
  return chords.slice(0, 3).map(chord => ({
    id: `chord-${chord.name}-${chord.first}-${chord.second}`.replace(/\s+/g, '-').toLowerCase(),
    kind: 'chord',
    tier: chord.tier,
    orb: chord.orb,
    chordFamily: chord.name,
    measurement: `${chord.first} ${chord.name} ${chord.second} · ${chord.angle}° · orb ${chord.orb.toFixed(3)}°`,
    canonicalSeats: [chord.firstSeat, chord.secondSeat].filter(Number.isInteger),
    themes: [],
    transmission: chordTransmission(chord.name, chord.first, chord.second),
  }))
}

// --- The pass ----------------------------------------------------------------

/**
 * @param glyphs    parsed codex seats
 * @param source    Map of name→longitude (legacy) carrying `.placements`, or a placements array
 * @param natal     [{ name, longitude }] natal planets, Moon included
 * @param live      [{ name, longitude }] present-sky planets
 * @param options   { instant, birthplace } — birthplace unlocks the Four Angles
 */
export function computeReading(glyphs, source, natal, live, options = {}) {
  const placementList = placementsFrom(glyphs, source)
  const seated = placementsBySeat(placementList, glyphs)
  const lonByName = source instanceof Map ? source : longitudeView(seated)

  const natalWithCommands = withCommands(natal)

  // i. Exact conjunctions — every seat against every natal planet, tightest first.
  const conjunctions = []
  natalWithCommands.forEach(planet => {
    seated.forEach((placement, seat) => {
      const glyph = glyphs.find(candidate => candidate.number === seat)
      if (!glyph) return
      const contact = conjunction(placement.longitude, planet.longitude)
      if (contact) conjunctions.push({ glyph, placement, planet: planet.name, ...contact })
    })
  })
  conjunctions.sort((first, second) =>
    CONJUNCTION_RANK[first.tier] - CONJUNCTION_RANK[second.tier]
    || first.orb - second.orb
    || first.glyph.number - second.glyph.number)

  // ii. The Planetary Courts — one court per natal planet, canon implementation.
  const courts = populatedCourts(planetaryCourts(glyphs, seated, natalWithCommands, MAJOR_BODIES))

  // iii. The Densest Cluster — counted over unique catalogue bodies.
  const cluster = densestCluster(glyphs, seated)

  // iv. The Four Angles — only when a birthplace resolved. Never inferred.
  const place = options.birthplace ? resolveBirthplace(options.birthplace) : null
  let angles = null
  let angleGeometry = null
  let angleConfidence = null
  if (place && options.instant) {
    // Without an IANA zone the entered clock time is read as UTC, which the
    // canon requires be flagged rather than silently trusted.
    angleConfidence = place.timeZone ? 'exact' : 'approximate'
    try {
      angleGeometry = chartAngles(new Date(options.instant), place.latitude, place.longitude)
      angles = angleContacts(glyphs, seated, angleGeometry, angleConfidence)
    } catch {
      angles = null
      angleGeometry = null
      angleConfidence = null
    }
  }

  const anglePoints = angleGeometry ? [
    { name: 'Ascendant', longitude: angleGeometry.ascendant, kind: 'angle' },
    { name: 'Midheaven', longitude: angleGeometry.midheaven, kind: 'angle' },
    { name: 'Descendant', longitude: angleGeometry.descendant, kind: 'angle' },
    { name: 'Imum Coeli', longitude: angleGeometry.imumCoeli, kind: 'angle' },
  ] : []

  // v. The Ten Gates — occupancy, and silence recorded as a finding.
  const gatePoints = [...natalWithCommands.map(planet => ({ name: planet.name, longitude: planet.longitude, kind: 'planet' })), ...anglePoints]
  const occupancy = gateOccupancy(glyphs, seated, gatePoints)
  const loudest = loudestGates(occupancy)
  const silent = silentGates(occupancy)
  const walk = initiatoryWalk(occupancy)
  const braid = officeBraid(occupancy)

  // vi. The Chord Lattice — every separation within orb, tiered.
  const seatPoints = [...seated.entries()].map(([seat, placement]) => ({
    name: placement.name, longitude: placement.longitude, seat, kind: 'seat',
  }))
  const latticePoints = [
    ...seatPoints,
    ...natalWithCommands.map(planet => ({ name: planet.name, longitude: planet.longitude, kind: 'planet' })),
    ...anglePoints,
  ]
  const families = strongestChords(latticePoints)
  // Flattened for the interface: `first`/`second` stay name strings, because the
  // lattice renderer joins them back to `points` by name.
  // A seam body sits at two seats, so both form the same geometric chord to any
  // third point — correct as structure, duplicated as a row. Collapse on the
  // unordered pair plus the chord family, keeping the tightest orb.
  const seenChords = new Map()
  const chords = [...families.entries()]
    .flatMap(([, contacts]) => contacts)
    .filter(contact => {
      const key = [contact.first.name, contact.second.name].sort().join('\u0000') + '\u0000' + contact.aspect
      const previous = seenChords.get(key)
      if (previous !== undefined && previous <= contact.orb) return false
      seenChords.set(key, contact.orb)
      return true
    })
    .map(contact => ({
      name: contact.aspect,
      aspect: contact.aspect,
      angle: contact.angle,
      first: contact.first.name,
      second: contact.second.name,
      firstSeat: contact.first.seat,
      secondSeat: contact.second.seat,
      orb: contact.orb,
      tier: contact.tier,
      separation: contact.separation,
    }))
    .sort((first, second) => CHORD_RANK[first.tier] - CHORD_RANK[second.tier] || first.orb - second.orb)

  // Today's activations — live sky against the natal field.
  const activationSet = crossChartActivations(glyphs, seated, natalWithCommands, live)
  const activations = activationSet.glyphContacts.map(contact => ({
    glyph: contact.natal.glyph,
    planet: contact.live.name,
    orb: contact.orb,
    tier: contact.tier,
  }))
  const activationTransmission = composeActivationTransmission(activationSet)

  // vii. Synthesis — ranked evidence, never exceeding what the chart supports.
  const evidence = [
    clusterEvidence(cluster, glyphs),
    ...angleEvidence(angles, angleConfidence),
    ...courtEvidence(courts),
    ...gateEvidence(loudest),
    ...chordEvidence(chords),
  ].filter(Boolean)

  const transmission = composeTransmission(evidence)
  const sentence = finalSentence(evidence)

  let packet = null
  try {
    packet = buildSynthesisPacket({
      chartKind: 'birth',
      angleConfidence: angleConfidence || 'unknown',
      evidence,
      glyphs,
      groups: GROUPS,
      chords: CHORDS.map(chord => ({ name: chord.name, angle: chord.angle })),
    })
  } catch {
    packet = null
  }

  // The lattice renderer joins chord ends to `points` by name, so every point a
  // chord can reach has to be here — seats, planets and angles alike. The shipped
  // interface built this list itself from seat names plus planets; angles were
  // not in it, so an angle-ended chord would have drawn nothing.
  const points = [
    ...seatPoints.map(point => ({ name: point.name, longitude: point.longitude, seat: point.seat })),
    ...natalWithCommands.map(planet => ({ name: planet.name, longitude: planet.longitude, planet: true })),
    ...anglePoints.map(point => ({ name: point.name, longitude: point.longitude, angle: true })),
  ]

  return {
    // Shapes the shipped interface already binds to.
    points,
    conjunctions: conjunctions.slice(0, 6),
    courts: courts.slice(0, 3).map(court => ({ planet: court.body.name, contacts: court.contacts })),
    chords: chords.slice(0, 5),
    activations: activations.slice(0, 3),

    // Layers iv-vii, now computed rather than described.
    angles,
    angleConfidence,
    angleGeometry,
    birthplace: place,
    gates: { occupancy, loudest, silent, walk, braid },
    cluster,
    lattice: { chords, families: [...families.entries()].map(([family, contacts]) => ({ family, contacts })) },
    synthesis: { ...transmission, sentence, activation: activationTransmission },
    packet,
  }
}


// ─────────────────────────────────────────────────────────────
// phone display overlay (applied once, at module init)
// ─────────────────────────────────────────────────────────────

applyPhoneDisplay(GROUPS, CHORDS)
